\"sv_79d1f523b37ca85b9da977e2\"}","69f0f2a29d245c2246d6dbfbaa5964612bbeff788c802dc5459a8cc0bd3378c9"],["chunk_7275d0f7ed4347f865939b0c","wiki/sources/key-management-zur-etcs-nutzung.md",0,"Inhalt","Europaweit werden fÃ¼r Fahrten auf Strecken mit ETCS-Level 2 digitale kryptographische SchlÃ¼ssel auf den ETCS-Fahrzeugen benÃ¶tigt, mit denen sie sich gegenÃ¼ber den ETCS-Zentralen (RBC) der jeweiligen Eisenbahninfrastruktur, die diese SchlÃ¼ssel kennen mÃ¼ssen, autorisieren.\n\nAls Eisenbahninfrastrukturbetreiber (EIU) ist die DB InfraGO AG verpflichtet den Eisenbahnverkehrsunternehmen (EVU) diese kryptographischen SchlÃ¼ssel fÃ¼r die Strecken mit ETCS-Level 2 auf ihrer Eisenbahninfrastruktur zur VerfÃ¼gung zu stellen. Diese kryptographischen SchlÃ¼ssel, die strecken- und fahrzeugspezifisch erzeugt werden, mÃ¼ssen jedoch bei den jeweiligen EIU beantragt werden. Dazu muss das EVU ein Key Management Center (KMC) betreiben oder einen Dritten (z. B. DB InfraGO AG) mit dem FÃ¼hren eines KMC beauftragen.\n\nZur SchlÃ¼sselbeantragung sendet das EVU den Antrag per E-Mail an die bearbeitende Stelle der DB InfraGO AG. Nach entsprechender PrÃ¼fung und Erzeugung, werden die SchlÃ¼ssel Ã¼ber ein manuelles Verfahren, das den Sicherheitsanforderungen genÃ¼gt, an das EVU oder die von ihm beauftragte Stelle Ã¼bergeben. Das EVU oder sein autorisierter Vertreter mÃ¼ssen die ihnen Ã¼bergebenen SchlÃ¼ssel grundsÃ¤tzlich kryptografisch sicher transportieren, speichern und auf dem ETCS-Fahrzeug installieren.\n\nAlle Informationen und Dokumente stehen Ihnen rechts oben zum Download zur VerfÃ¼gung.\n\n[![](https://www.dbinfrago.com/resource/blob/13885858/56b1c536883582f0f461215aa409720c/Test-Bild-Hinweis-KMC-Migration-data.png)](https://www.dbinfrago.com/resource/blob/13885858/56b1c536883582f0f461215aa409720c/Test-Bild-Hinweis-KMC-Migration-data.png \"Ã–ffne GroÃŸbildansicht\")",181,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/etcs/anforderungen/key-management-11089662\",\"normalized_sha256\":\"5dfa9d0fd7f445d25d88eb3e58b33a163154f19442ef35fd09150b77439e46c0\",\"page\":null,\"source_id\":\"src_b3d6ae245fff20d2ab1f\",\"source_sha256\":\"e5bd7069d5ec2155aab604ae64b66958d98c1ce357bcfd5a924fe2451e4d5b8a\",\"source_version_id\":\"sv_fe91e17ce50ed45a6f56b07c\"}","42b19359d683cddbc3dae5955a564b52ce67c047454160d2d90d3c3597fcd90f"],["chunk_aa3f8737153d1af489aaaf57","wiki/sources/kickoff-ende-zu-ende-kundentests-ttt-mit-identifiern-data.md",0,"Seite 1","Kickoff: Ende-zu-Ende\n\nKundentests TAF/TAP TSI mit\n\nIdentifiern\n\n11.03.2026",8,"{\"canonical_url\":null,\"normalized_sha256\":\"bb6ff0626b6fa4b8f8b9a0b50e5fb3ddfcc3702fc886b64242b657608bfb9268\",\"page\":1,\"source_id\":\"src_2262169b6f00111ef4dc\",\"source_sha256\":\"97504436bbb9c084e054648e4988ff62e02616b1a292226cbfdbe64d32f1a6a5\",\"source_version_id\":\"sv_fa49b150c4d3a22a8072376f\"}","8e52a9955de7672c3490d5da529a5f88a1b0ebb6459f29ad819c9e147127cc09"],["chunk_c163d9bc507c8494318d0bf6","wiki/sources/kickoff-ende-zu-ende-kundentests-ttt-mit-identifiern-data.md",1,"Seite 2","Meeting Agenda\n\nTOP Zeit Thema Verantwortlich\n\n1 10:30 â€“ 10:50 Ãœberblick TAF/TAP TSI mit Identifiern Andreas Schumann\n\n2 10:50 â€“ 11:00 Fragerunde 1 alle\n\n3 11:00 â€“ 11:20 Testziele DÃ¶ne Ak / Heike Sperber\n\n4 11:20 â€“ 11:35 Fragerunde 2 alle\n\n5 11:35 â€“ 11:45 Anmeldung zum Test DÃ¶ne Ak\n\n6 11:45 â€“ 11:55 Fragerunde 3 alle\n\n7 11:55 â€“ 12:00 Ausblick DÃ¶ne Ak\n\nDB InfraGO | Kickoff Kundentests E2E TAF/TAP TSI mit ID | 11.03.2026 2",77,"{\"canonical_url\":null,\"normalized_sha256\":\"bb6ff0626b6fa4b8f8b9a0b50e5fb3ddfcc3702fc886b64242b657608bfb9268\",\"page\":2,\"source_id\":\"src_2262169b6f00111ef4dc\",\"source_sha256\":\"97504436bbb9c084e054648e4988ff62e02616b1a292226cbfdbe64d32f1a6a5\",\"source_version_id\":\"sv_fa49b150c4d3a22a8072376f\"}","0ec7768b27d223ceb6039fbb162d50b161e14093238f83d428bd8d190a63b6f7"],["chunk_3546dc4ceba4e1a581afe8da","wiki/sources/kickoff-ende-zu-ende-kundentests-ttt-mi