INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_991cade4ec8ba5c9fde37143","wiki/sources/ril-301-inb-2026-data.md",7,"Seite 7","Richtlinie\n\nSignalordnung, Bahnbetrieb international Signalbuch\n\nVorbemerkungen zum Signalbuch 301.0001\n\nSeite 1\n\n* (1) Die Richtlinien 301 â€“ Signalbuch â€“ enthalten Inhalt des\n\nSignalbuchs\n\n- die wesentlichen Bestimmungen Ã¼ber die bei der DB AG verwendeten Signale der Eisenbahn-Signalordnung (ESO),\n\n- die den AusfÃ¼hrungsbestimmungen (AB) entsprechenden Bestimmungen,\n\n- Bestimmungen Ã¼ber die Anwendung der von der ESO abweichenden Signale mit vorÃ¼bergehender GÃ¼ltigkeit,\n\n- ZusÃ¤tze der DB AG sowie\n\n- Orientierungszeichen.\n\n(2) FÃ¼r die Aufstellung ortsfester Signale gilt das entsprechende technische Re- Technisches\n\ngelwerk. Regelwerk\n\n(3) Wo das Signalbuch zusÃ¤tzliche Bestimmungen erfordert, die in verschieden- ZusÃ¤tzliche\n\nartigen Einrichtungen und Ã¶rtlichen VerhÃ¤ltnissen begrÃ¼ndet sind, werden sie Bestimmunbekannt gegeben: gen zum Signalbuch\n\n- im Fahrplan,\n\n- in der Zusammenstellung der vorÃ¼bergehenden Langsamfahrstellen und\n\nanderen Besonderheiten (La),\n\n- in der Betriebs- und Bauanweisung (Betra),\n\n- in Ã¶rtlichen ZusÃ¤tzen (diese kÃ¶nnen im Betriebsstellenbuch, anderen Ã¶rtlichen Unterlagen â€“ soweit kein Betriebsstellenbuch vorhanden ist â€“ und im\n\nStreckenbuch enthalten sein),\n\n- bei Anwendung der FV-NE in der Sammlung betrieblicher Weisungen.\n\n(4) Soweit in dieser Richtlinie einzelne Bestimmungen nur in den BundeslÃ¤ndern DS 301,\n\nSchleswig-Holstein, Hamburg, Niedersachsen, Bremen, Nordrhein-Westfalen, Geltungsbe-\n\nHessen, Rheinland-Pfalz, Saarland, Baden-WÃ¼rttemberg und Bayern ange- reich\n\nwendet werden, ist bei der Bestimmung, in der AbschnittsÃ¼berschrift oder im\n\n* Richtlinientitel der Vermerk â€ž(DS 301)â€œ angebracht.\n\n(5) Soweit in dieser Richtlinie einzelne Bestimmungen nur in den BundeslÃ¤ndern DV 301,",218,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":7,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","c53980587022f3329692cddf2d6014ad63d926adf6dface8561ba8ba4cd161c4"],["chunk_16303d97cd0b1c369491fc4a","wiki/sources/ril-301-inb-2026-data.md",8,"Seite 7","Mecklenburg-Vorpommern, Brandenburg, Berlin, Sachsen-Anhalt, Sachsen Geltungsbeund ThÃ¼ringen angewendet werden, ist bei der Bestimmung, in der Ab- reich\n\n* schnittsÃ¼berschrift oder im Richtlinientitel der Vermerk â€ž(DV 301)â€œ angebracht.\n\n(6) Der Wechsel der betrieblichen Regeln und damit auch der Geltungsbereiche Wechsel der\n\nder DS 301 und der DV 301 sind in der La genannt. Geltungsbereiche\n\nï±\n\nFachautor: I.NPB 4(B); Thomas Richter; Tel.: (030) 297 21 461 GÃ¼ltig ab: 13.12.2020",67,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":7,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","3f804aa564557e944bd06dc545d326362cf7f9f8a1c324385d521bc450a80273"],["chunk_790c10d11a28cfd34c635349","wiki/sources/ril-301-inb-2026-data.md",9,"Seite 8","Richtlinie\n\nSignalordnung, Bahnbetrieb international Signalbuch\n\nAllgemeine Bestimmungen 301.0002\n\nSeite 1\n\n1 Begriffsbestimmungen\n\nDie Signale dÃ¼rfen nur in den vorgeschriebenen Formen, Farben und Klangarten und fÃ¼r den vorgesehenen Zweck verwendet werden.\n\na) Signal Signal\n\nEin Signal ist ein sichtbares oder hÃ¶rbares Zeichen mit einer festgelegten\n\nInformation zur GewÃ¤hrleistung des sicheren Bewegens von Eisenbahnfahrzeugen.\n\nb) Signalbegriff Signalbegriff\n\nDer Signalbegriff ist die Kurzbezeichnung eines Signals (z. B. Zs 1), die bei\n\neinigen Signalen durch eine Langbezeichnung ergÃ¤nzt ist (z. B. Ersatzsignal).\n\nc) Signalbedeutung Signalbedeu-\n\nDie Signalbedeutung ist die verbale Darstellung der Information, die ein tung\n\nSignal gibt.\n\nd) Signalbeschreibung Signalbe-\n\nDie Signalbeschreibung ist die verbale Darstellung des Signalbildes oder schreibung\n\ndes Signaltones.\n\ne) Signalbild Signalbild\n\nDas Signalbild umfasst die fÃ¼r ein sichtbares Signal festgelegten Formen,\n\nFarben und Merkmale (z. B. Symbole, Buchstaben, Zahlen).\n\nEin sichtbares Signal kann ein Formsignal, Lichtsignal oder ein Handsignal\n\nsein.\n\nf) Signalton Signalton\n\nDer Signalton umfasst das hÃ¶rbare Signal, das aus einem oder mehreren\n\nTÃ¶nen besteht, fÃ¼r die die Dauer und, wenn erforderlich, auch die TonhÃ¶he\n\nfestgelegt sind.\n\n* g) Ortsfeste signaltechnische Einrichtungen, die Signale nach a) zeigen, wer- ortsfeste\n\n* den nach ihrer Funktion bezeichnet. signaltechnische Einrichtungen\n\nEs gibt z. B.\n\n- Hauptsignale,\n\n- Vorsignale,\n\n- Sperrsignale,\n\n* - Ãœberwachungssignale,\n\n* - Weichensignale,\n\n* - AbdrÃ¼cksignale.\n\nFachautor: I.NBB 4; Thomas Richter; Tel.: (030) 297- 21 461 GÃ¼ltig ab: 15.12.2024",221,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":8,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","daf807a7c8f63248d60e27a5e3430961878e0932b811899e1377e5bac77efba6"],["chunk_1812d15842de1e29e2479650","wiki/sources/ril-301-inb-2026-data.md",10,"Seite 9","Allgemeine Bestimmungen 301.0002\n\nSeite 2\n\nweiÃŸ