INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_b6b822cb3f43cd6b1793f8d9","wiki/sources/ril-301-inb-2026-data.md",27,"Seite 21","Hp-Signale 301.0101\n\nSeite 2\n\nBeschreibung (3) Lichtsignal:\n\nLichtsignal\n\nEin rotes Licht oder zwei rote Lichter nebeneinander.\n\n*\n\n(4) Das Signal Hp 0 wird gezeigt am Hauptsignal oder am Sperrsignal.\n\nHp 0 in (5) Wird am Hauptsignal zusÃ¤tzlich zum Signal Hp 0 das Signal Sh 1 bzw. das *\n\nVerbindung Signal Ra 12 (DV 301) gezeigt, ist das Haltegebot fÃ¼r Rangierfahrten aufge- *\n\nmit Sh 1 bzw. hoben.\n\nRa 12 (Dv 301)\n\nAm Hauptsignal mit zwei roten Lichtern verlischt beim Aufleuchten des Signals Sh 1 (DS 301) ein rotes Licht.\n\n3 Signal Hp 1\n\nBedeutung (1) Fahrt.\n\nBeschreibung (2) Formsignal:\n\nFormsignal\n\nTageszeichen:\n\nEin SignalflÃ¼gel â€“ bei zweiflÃ¼gligen Signalen der obere FlÃ¼gel â€“ zeigt schrÃ¤g\n\nnach rechts aufwÃ¤rts.\n\nGÃ¼ltig ab: 15.12.2024",119,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":21,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","54fb0d59ce2a4c540107757ae4fcc89c928ad2595d03a227019adbec39c9f594"],["chunk_36c99b8749d3d1ca80593d7c","wiki/sources/ril-301-inb-2026-data.md",28,"Seite 22","Hp-Signale 301.0101\n\nSeite 3\n\nNachtzeichen:\n\nEin grÃ¼nes Licht.\n\n(3) Lichtsignal: Beschreibung\n\nLichtsignal\n\nEin grÃ¼nes Licht.\n\n(4) Das Signal erlaubt die Fahrt mit der im Fahrplan zugelassenen Geschwindigkeit, sofern sie nicht durch andere Signale oder besondere Anordnungen eingeschrÃ¤nkt ist.\n\n4 Signal Hp 2\n\n(1) Langsamfahrt. Bedeutung\n\n(2) Formsignal: Beschreibung\n\nFormsignal\n\nTageszeichen:\n\nZwei SignalflÃ¼gel zeigen schrÃ¤g nach rechts aufwÃ¤rts.\n\nGÃ¼ltig ab: 15.12.2024",60,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":22,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","233d5332bed2a26e03a70073d7ac938886c5da72d42a4864ff2c101fdf794dc5"],["chunk_e88a41fa5343cc62dffe4358","wiki/sources/ril-301-inb-2026-data.md",29,"Seite 23","Hp-Signale 301.0101\n\nSeite 4\n\nNachtzeichen:\n\nEin grÃ¼nes und senkrecht darunter ein gelbes Licht.\n\nBeschreibung (3) Lichtsignal:\n\nLichtsignal\n\nEin grÃ¼nes und senkrecht darunter ein gelbes Licht.\n\nGeschwindig- (4) Das Signal schreibt eine GeschwindigkeitsbeschrÃ¤nkung auf 40 km/h vor,\n\nkeitsbe- wenn nicht eine abweichende Geschwindigkeit durch Signal Zs 3 angezeigt\n\nschrÃ¤nkung wird. Der Infrastrukturunternehmer kann andere abweichende Geschwindigkeiten bekannt geben. Bei den NE ist das im Fahrplan, in der SbV oder in der\n\nLa angegeben.\n\nBei den Eisenbahnen des Bundes werden andere abweichende Geschwindigkeiten im Fahrplan oder in der La angegeben.\n\nDie GeschwindigkeitsbeschrÃ¤nkung gilt vom Hauptsignal ab fÃ¼r den anschlieÃŸenden Weichenbereich.\n\nï±\n\nGÃ¼ltig ab: 15.12.2024",102,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":23,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","d81616b1cc656fe4f5e0a34be9d073ff955398f77a6492397f9a185bc1845199"],["chunk_b173fd74602453ca71231534","wiki/sources/ril-301-inb-2026-data.md",30,"Seite 24","Richtlinie\n\nSignalordnung, Bahnbetrieb international Signalbuch\n\nKombinationssignale (Ks) 301.0102\n\nSeite 1\n\n* 1 Allgemeine Bestimmungen zu den Kombinationssignalen\n\n* (1) Die Ks-Signale gelten nur fÃ¼r Zugfahrten. Geltung der\n\nKs-Signale\n\n* (2) (bleibt frei)\n\n* (3) Hauptsignale mit Vorsignalfunktion, die in einem um mehr als 5% verkÃ¼rzten VerkÃ¼rzter\n\nAbstand des Bremswegs der Strecke vor dem zugehÃ¶rigen Signal stehen, Abstand des\n\nzeigen bei Signal Ks 1 mit Zs 3v und bei Signal Ks 2 ein weiÃŸes Zusatzlicht Bremswegs\n\nÃ¼ber dem Signallicht.\n\noder\n\nVorsignal-\n\n(4) Vorsignalwiederholer zeigen bei Ks 1 mit Zs 3v und bei Ks 2 ein weiÃŸes Zuwiederholer\n\nsatzlicht unter dem Signallicht.\n\noder\n\nFachautor: I.NBB 4; Thomas Richter; Tel.: (030) 297- 21 461 GÃ¼ltig ab: 15.12.2024",114,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac30b6e6a8a34b68df5ac16f2c30\",\"page\":24,\"source_id\":\"src_de2b663a72807ea67d48\",\"source_sha256\":\"25cc06fe17dea707cb0be9b58a57e9967c2002c844b68d12ab23e819498203d3\",\"source_version_id\":\"sv_f11f03ab26352667021becc9\"}","235d7fe331b08b6b900312a105046b115c6f260953c66ce962f7f306bb10d36e"],["chunk_235c22038a324ac9e2a30b2c","wiki/sources/ril-301-inb-2026-data.md",31,"Seite 25","Kombinationssignale (Ks) 301.0102\n\nSeite 2\n\n2 Signal Ks 1\n\nBedeutung (1) Fahrt\n\nBeschreibung (2) Ein grÃ¼nes Licht bzw. ein grÃ¼nes Blinklicht.\n\nGrÃ¼nes (3) Das Signal Ks 1 blinkt, wenn an dem Vorsignal oder Hauptsignal mit Vorsig- *\n\nBlinklicht nalfunktion zusÃ¤tzlich ein Signal Zs 3v gezeigt wird. *\n\nGeschwindig- (4) Das an einem Hauptsignal gezeigte Signal erlaubt die Anwendung der im\n\nkeit Fahrplan zugelassenen Geschwindigkeit.\n\n3 Signal Ks 2\n\nBedeutung (1) Halt erwarten.\n\nBeschreibung (2) Ein gelbes Licht.\n\n(3) Das Signal erlaubt die Vorbeifahrt und kÃ¼ndigt Halt an.\n\nï±\n\nGÃ¼ltig ab: 15.12.2024",91,"{\"canonical_url\":null,\"normalized_sha256\":\"5bd5b80e5102af117ed153ea071e22393821ac3